const $=s=>document.querySelector(s);let trip='Hourly',pending;let bookings=[];try{bookings=JSON.parse(localStorage.getItem('drivermate-bookings')||'[]');if(!Array.isArray(bookings))bookings=[]}catch{}const today=new Date();const localDate=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;$('#date').min=localDate(today);$('#date').value=localDate(today);function price(){return Number($('#duration').value)*200-1}function update(){ $('#fare').textContent='₹'+price().toLocaleString('en-IN');$('#fare-note').textContent=`For ${$('#duration').value} hours · demo pricing`}$('#duration').onchange=update;document.querySelectorAll('[data-trip]').forEach(b=>b.onclick=()=>{trip=b.dataset.trip;document.querySelectorAll('[data-trip]').forEach(x=>x.classList.toggle('active',x===b))});function count(){$('#count').textContent=bookings.filter(b=>b.status!=='Cancelled').length}count();function save(){localStorage.setItem('drivermate-bookings',JSON.stringify(bookings));count()}function open(title){$('#modal-title').textContent=title;$('#modal-body').replaceChildren();$('#modal').showModal()}function paragraph(text,cls='notice'){const p=document.createElement('p');p.className=cls;p.textContent=text;$('#modal-body').append(p)}function detail(k,v){const p=document.createElement('div');p.className='detail';const s=document.createElement('span');s.textContent=k;const b=document.createElement('b');b.textContent=v;p.append(s,b);$('#modal-body').append(p)}function button(text,fn,cls='primary'){const b=document.createElement('button');b.className=cls;b.textContent=text;b.onclick=fn;return b}$('#close').onclick=()=>$('#modal').close();$('#modal').onclick=e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}};$('#booking-form').onsubmit=e=>{e.preventDefault();if(!$('#pickup').value.trim())return $('#pickup').setCustomValidity('Enter a pickup location.');const at=new Date(`${$('#date').value}T${$('#time').value}`);if(at<=new Date()){ $('#time').setCustomValidity('Choose a future pickup time.');$('#time').reportValidity();return}pending={id:crypto.randomUUID(),trip,pickup:$('#pickup').value.trim(),date:$('#date').value,time:$('#time').value,duration:$('#duration').value,car:$('#car').value,fare:price(),status:'Demo request'};open('Review your booking');detail('Trip',pending.trip);detail('Pickup',pending.pickup);detail('When',`${pending.date} at ${pending.time}`);detail('Your car',pending.car);detail('Duration',pending.duration+' hours');detail('Demo estimate','₹'+pending.fare);paragraph('This saves a demo booking on this browser only. No payment is collected, no driver is assigned, and these sample prices are not live fares.');$('#modal-body').append(button('Save demo booking →',()=>{try{bookings.push(pending);save();$('#modal').close();showBookings()}catch{paragraph('Your browser could not save this booking. Please enable local storage.')}}))};['pickup','date','time'].forEach(id=>$('#'+id).addEventListener('input',()=>{$('#pickup').setCustomValidity('');$('#time').setCustomValidity('')}));function showBookings(){open('My bookings');paragraph('Demo bookings saved on this browser.');if(!bookings.length)return paragraph('No bookings yet. Your next plan starts here.','empty');bookings.slice().reverse().forEach(b=>{const box=document.createElement('div');box.className='booking-item';const title=document.createElement('strong');title.textContent=b.pickup;const p=document.createElement('p');p.textContent=`${b.date} · ${b.time} · ${b.duration}h · ${b.car}`;const status=document.createElement('p');status.textContent=`${b.status} · ₹${b.fare}`;box.append(title,p,status);if(b.status!=='Cancelled')box.append(button('Cancel demo booking',()=>{b.status='Cancelled';save();$('#modal').close();showBookings()},'cancel'));$('#modal-body').append(box)})}function driver(){open('Drive with DriveMate');paragraph('Explore driver registration. This demo stores your interest on this device only; it does not submit an application or verify your licence.');const f=document.createElement('form');f.innerHTML='<label>Full name<input name="name" autocomplete="name" required maxlength="80"></label><label>Mobile number<input name="phone" type="tel" autocomplete="tel" pattern="[0-9+() -]{10,16}" required placeholder="Your mobile number"></label><label>City<input name="city" required maxlength="80" value="Bengaluru" readonly></label><label>Driving experience<select name="experience"><option>Less than 1 year</option><option>1–3 years</option><option>3–5 years</option><option>5+ years</option></select></label><label>Car types<select name="car"><option>Manual and automatic</option><option>Manual only</option><option>Automatic only</option></select></label><button class="primary" type="submit">Save demo profile →</button>';f.onsubmit=e=>{e.preventDefault();try{localStorage.setItem('drivermate-driver',JSON.stringify(Object.fromEntries(new FormData(f))));$('#modal-body').replaceChildren();paragraph('Your demo profile is saved on this browser. Driver applications are not open yet.');}catch{paragraph('Your browser could not save the profile.')}};$('#modal-body').append(f)}document.querySelectorAll('[data-action]').forEach(b=>b.onclick=e=>{e.preventDefault();b.dataset.action==='driver'?driver():showBookings()});
